// Independent left-to-right recurrence. Uses only this review's matrix primitives.
#define main small_fixture_main
#include "independent.cpp"
#undef main
void production_guards(){rlimit c,a;getrlimit(RLIMIT_CPU,&c);getrlimit(RLIMIT_AS,&a);test(c.rlim_cur==27&&c.rlim_max==27,"CPU27");test(a.rlim_cur==256ul*1024*1024&&a.rlim_max==a.rlim_cur,"AS256");cpu_set_t set;CPU_ZERO(&set);test(sched_getaffinity(0,sizeof(set),&set)==0&&CPU_COUNT(&set)==1&&CPU_ISSET(5,&set),"CPU5");struct sigaction action;sigaction(SIGXCPU,nullptr,&action);sigset_t mask;sigprocmask(SIG_BLOCK,nullptr,&mask);test(action.sa_handler==SIG_DFL&&!sigismember(&mask,SIGXCPU),"SIGXCPU");int death;prctl(PR_GET_PDEATHSIG,&death);test(death==SIGKILL,"PDEATHSIG");std::cerr<<"POSTEXEC_CPU27_AS256_CPU5_SIGXCPU_DEFAULT_UNBLOCKED_PDEATHSIG9\n";}
int main(int argc,char**argv){try{production_guards();test(argc==3,"arguments");std::ifstream data(argv[1]),expected(argv[2]);int n;data>>n;test(n==11,"block count");I N,H,B;const int sizes[11]={1,8,32,80,136,162,136,80,32,8,1};for(int block=0;block<11;++block){int charge,d;data>>charge>>d;test(charge==2*block-10&&d==sizes[block],"sector");M T(d),O(d),U(d),V(d);for(auto*m:{&T,&O,&U,&V})for(auto&x:m->x)data>>x;test(bool(data),"truncated input");M P=T,R=O;int exponent=1;
 // Process the five remaining bits of 61 = binary 111101.
 for(int bit=4;bit>=0;--bit){M square=times(P,P);M doubled=plus(times(P,R),times(R,P),exponent%2?-1:1);P=std::move(square);R=std::move(doubled);exponent*=2;if((61>>bit)&1){M next=plus(times(P,O),times(R,T),-1);P=times(P,T);R=std::move(next);++exponent;}}
 test(exponent==61,"final exponent");M P62=times(P,T),T2=times(T,T);I norm=dottrace(P62,T2),h=64*dottrace(P62,O),same=dottrace(P62,U),adj=dottrace(P,V),disj=dottrace(R,O),b=64*(same-adj+disj);std::array<I,6>computed={norm,h,b,same,adj,disj};int q;expected>>q;test(q==charge,"checkpoint charge");for(const auto&value:computed){I wanted;expected>>wanted;test(bool(expected)&&wanted==value,"independent64 checkpoint mismatch");}N+=norm;H+=h;B+=b;std::cout<<"BLOCK_MATCH charge="<<charge<<" dimension="<<d<<"\n";std::cout.flush();}
 std::string extra;test(!(data>>extra)&&!(expected>>extra),"trailing data");test(N>0&&B>=0&&B<=9216*N,"physical range");std::cout<<"N0_64="<<N<<"\nH0_64="<<H<<"\nB2_64="<<B<<"\nINDEPENDENT64_ALL_BLOCKS_AND_TOTALS_PASS\n";return 0;}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<"\n";return 2;}}
